steps.script:
var d = tree.root.get_node_or_null("/root/AbilityChoiceDialog")
if d != null and d.visible:
	d.get_ok_button().pressed.emit()
	return true
return false

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
var confirm_at = t.find("Confirm Targets")
var reaim_at = t.find("walks da targets")
return confirm_at != -1 and reaim_at != -1 and confirm_at < reaim_at

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay/Center/Panel/Row/DecisionCol/ResultPanel/DoneButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/ShootingPhaseSummaryDialog/Content/Actions/ConfirmEndShooting")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
return false
